export interface DubbingLiveStatusExportInfo {
    /** Target language (BCP-47). */
    target_language?: string | undefined;
    /** Export status, e.g. `completed`, `in_progress`, `failed`. */
    status?: string | undefined;
    /** Signed URL for the dubbed video. */
    dubbed_video_url?: string | undefined;
    /** Signed URL for the original video. */
    original_video_url?: string | undefined;
    /** Video duration in seconds. */
    duration?: number | undefined;
    /** File size in bytes. */
    file_size?: number | undefined;
}
